window.DECK_NOTES=[{"title": "Derrière les flags", "time": "20 secondes", "say": "« Ces archives racontent des challenges résolus pendant le CTF. Nous allons reprendre les raisonnements, un à un, avec des schémas et les preuves conservées. On commence par un cas très visuel : un texte transformé en nombres, puis retrouvé grâce aux tables publiques de GPT-2. »", "details": "", "qa": "", "sources": "Journaux des challenges, PowerPoint Tapo et fichiers fournis.", "gap": "Schémas pédagogiques fondés sur les fichiers. Les animations ne représentent pas les temps réels du solve.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Embeddings — le défi", "time": "45–60 secondes", "say": "« On nous donne un fichier appelé Dockerfile.json. Malgré son nom, il contient du JSON et des nombres. Il indique le modèle GPT-2. Il y a 24 groupes de 768 nombres. Le flag a été transformé en cette représentation. Notre mission est de retrouver le texte qui se cache derrière. »", "details": "Le fichier contient session_id, model=\"gpt2\" et inputs_embeds. La forme 24 × 768 est directement vérifiable dans le JSON. Un vecteur est simplement une liste de nombres. Un token est un morceau de texte : parfois un mot, parfois quelques lettres, parfois un signe.", "qa": "Faut-il connaître le machine learning ? Non : il suffit de comprendre une table de correspondance et une addition. Le schéma explique la structure confirmée par la résolution, pas une hypothèse prise pour un fait au début.", "sources": "LOST_IN_EMBEDDING · JOURNAL 20:05, 20:09 · DOCKERFILE.JSON", "gap": "Schémas pédagogiques fondés sur les fichiers. Les animations ne représentent pas les temps réels du solve.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Embeddings — le dictionnaire", "time": "45–60 secondes", "say": "« Un embedding, ici, c’est une liste de nombres associée à un morceau de texte. Imaginez un dictionnaire : à gauche, “BA” ; à droite, 768 nombres. GPT-2 possède cette table. Dans notre fichier, une deuxième liste de nombres a été ajoutée pour indiquer la place du morceau dans le texte. Et les deux tables sont disponibles dans le modèle public. »", "details": "Les tables sont wte, avec 50 257 lignes de tokens, et wpe, avec les positions. Dans ce challenge, vecteur[i] = wte[token_i] + wpe[i]. Les tokens BA, 26 et { correspondent effectivement aux trois premiers tokens retrouvés (4339, 2075, 90). Les barres sont une illustration, pas une projection calculée des 768 dimensions.", "qa": "Un token est-il une lettre ? Pas forcément. Les trois premiers sont BA, 26 et {. Il ne faut donc pas annoncer 24 lettres : il y a 24 morceaux. Les tables ont été téléchargées pendant le CTF après autorisation ; rien n’a été téléchargé pour cette présentation.", "sources": "LOST_IN_EMBEDDING · CLAUDE/WRITEUP.MD, SECTIONS 2–4", "gap": "Schémas pédagogiques fondés sur les fichiers. Les animations ne représentent pas les temps réels du solve.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Embeddings — une addition réversible", "time": "45–60 secondes", "say": "« Prenons trois nombres pour que le principe tienne sur un écran. Le token vaut deux, cinq, un. Sa position vaut un, zéro, trois. En additionnant colonne par colonne, on obtient trois, cinq, quatre. On connaît la position : on la retire et on retrouve deux, cinq, un. Il ne reste qu’à chercher cette ligne dans le dictionnaire. Dans le vrai fichier, c’est la même opération sur 768 nombres. »", "details": "Exemple construit pour expliquer une addition de vecteurs. Ces valeurs ne représentent ni un token GPT-2 réel ni une ligne du fichier. La structure confirmée est E[i] = wte[token_i] + wpe[i], avec des écarts d’arrondi.", "qa": "Pourquoi ne pas demander à un chatbot ? Il s’agit de retrouver des lignes dans les tables, pas de générer une phrase plausible.", "sources": "ILLUSTRATION PÉDAGOGIQUE · STRUCTURE CONFIRMÉE DANS CLAUDE/WRITEUP.MD", "gap": "Les valeurs sont fictives ; la structure du calcul correspond au challenge.", "cues": ["Montrer les deux listes à additionner.", "→ Les nombres reçus et la position connue.", "→ Retrouver la ligne de départ.", "→ Transposer aux 768 dimensions."]}, {"title": "Embeddings — le chemin inverse", "time": "45–60 secondes", "say": "« Prenons le premier groupe. Nous savons qu’il contient les nombres du morceau et ceux de sa position. On retire les nombres de position. Il reste presque exactement une ligne du dictionnaire. On cherche la ligne la plus proche : elle correspond à “BA”. Puis on refait la même chose pour le deuxième groupe, puis le troisième, jusqu’au bout. »", "details": "L’agent a chargé les poids publics de GPT-2, soustrait wpe pour les positions 0 à 23, puis comparé chaque vecteur aux 50 257 lignes de wte avec une distance euclidienne. Les indices retrouvés ont été passés au tokenizer pour reconstituer la chaîne.", "qa": "Pourquoi « la plus proche » et pas « identique » ? Les nombres conservés présentent de très petits écarts. Après correction, les distances observées sont de 0,000 à 0,004. Le plus proche voisin suffit. Il n’y a pas de génération de texte ou de prompt envoyé à un chatbot.", "sources": "LOST_IN_EMBEDDING · CLAUDE/SRC/INVERT.PY · CLAUDE/OUT-01.TXT", "gap": "Schémas pédagogiques fondés sur les fichiers. Les animations ne représentent pas les temps réels du solve.", "cues": ["Lire un groupe de nombres.", "→ Retirer sa composante de position.", "→ Chercher le token le plus proche.", "→ Répéter et assembler."]}, {"title": "Embeddings — vérifier plutôt que deviner", "time": "45–60 secondes", "say": "« L’agent compare d’abord les nombres directement à la table : le flag apparaît déjà. Mais les distances restent élevées. Après retrait de la position, les mêmes tokens sont retrouvés et les distances deviennent presque nulles. Cette correction explique les nombres reçus, en plus de produire un texte plausible. »", "details": "La sortie conservée donne les distances euclidiennes 3,5 à 9,9 pour les vecteurs bruts et 0,000 à 0,004 après soustraction de wpe. Les cosinus passent de 0,35–0,74 à 1,000. Les bandes sont schématiques, sans échelle quantitative commune.", "qa": "La première méthode avait-elle échoué ? Non : elle donnait déjà le bon texte. La correction confirme la structure.", "sources": "LOST_IN_EMBEDDING · CLAUDE/OUT-01.TXT · CLAUDE/WRITEUP.MD §4", "gap": "Mesures lues dans la sortie conservée. Aucune recherche relancée.", "cues": ["Comparer les vecteurs bruts.", "→ Retirer la position : les distances chutent.", "→ Le texte retrouvé reste identique.", "→ Conclure sur les correspondances presque exactes."]}, {"title": "Embeddings — le résultat", "time": "45–60 secondes", "say": "« En assemblant les morceaux, on retrouve le flag. La sortie conservée le montre, et les mesures confirment des correspondances presque exactes. La leçon : ici, remplacer le texte par ses embeddings ne le rendait pas secret. On connaissait le modèle, ses tables étaient publiques, et l’opération pouvait être inversée. »\n\nClin d’œil facultatif à dire : « Il avait changé de tenue, mais laissé son nom dans le vestiaire. »", "details": "Le résultat brut, avant soustraction des positions, donnait déjà les bons tokens, avec des distances bien plus grandes. La correction rend la correspondance convaincante : distances de 0,000 à 0,004 et similarités cosinus affichées à 1,000. Le script final est claude/src/invert.py ; la sortie est claude/out-01.txt.", "qa": "Est-ce vrai de tous les embeddings ? Cette démonstration porte sur ces embeddings d’entrée GPT-2, formés par une table de tokens et une table de positions. Il ne faut pas présenter cette recette comme une inversion universelle de tous les vecteurs de tous les modèles.", "sources": "LOST_IN_EMBEDDING · JOURNAL 20:09 · CLAUDE/OUT-01.TXT", "gap": "La capture haute résolution a été produite après l’événement à partir de la sortie sauvegardée. Le solve n’a pas été relancé pour cette présentation.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "ID, please — deux portes d’entrée", "time": "45–60 secondes", "say": "« Le site propose une connexion avec un mot de passe, ou avec Google. Dans la connexion Google, on transmet au site une attestation qui indique quel compte se connecte. Cette attestation devrait être vérifiée. Or le chemin appelé “legacy” accepte même une attestation sans signature. On peut donc fabriquer ce qu’elle contient. Mais cela ne suffit pas encore : il faut désigner le bon compte. »", "details": "Les journaux décrivent POST /member/auth/socialLogin, qui accepte un JWT non signé avec alg:none et répond “legacy compatibility login”. JWT est le format de l’attestation. Le champ sub contient l’identifiant du compte Google. La session créée par l’application est ensuite un cookie opaque, distinct de ce JWT. Les détails du format ne sont pas nécessaires pour suivre la démonstration.", "qa": "Pourquoi une signature ? Elle permet au site de contrôler l’origine et l’intégrité de l’attestation. Lire un numéro dans un document qu’un visiteur peut fabriquer ne prouve pas que ce visiteur possède le compte correspondant.", "sources": "ID_PLEASE · JOURNAL 18:39, 20:25 · WRITEUP, SECTIONS 1–2", "gap": "Schéma pédagogique : aucune capture de connexion n’est présentée comme une preuve. L’analyse reprend les observations conservées ; aucune requête n’a été relancée.", "cues": ["Présenter les deux modes de connexion.", "→ Expliquer l’attestation Google en mots simples.", "→ Révéler l’absence de vérification de signature."]}, {"title": "ID, please — la mauvaise identité", "time": "45–60 secondes", "say": "« Les premières tentatives étaient intuitives : écrire “je suis admin” dans le document, ou mettre l’email de l’admin. Elles échouaient. Le rôle venait du compte déjà enregistré dans la base, et le site retrouvait ce compte avec un champ appelé sub. Même email, mais autre sub : autre compte, simple utilisateur. Le vrai problème devient donc : comment retrouver le numéro du compte admin ? »\n\nClin d’œil facultatif à dire : « Je me suis autoproclamé chef. Même le serveur a trouvé ça un peu rapide. »", "details": "Le comportement a été vérifié par plusieurs agents : même sub, même membre ; nouveau sub avec un email déjà connu, nouveau membre. Les champs role/isAdmin ne changent pas le rôle. L’enquête a aussi écarté de nombreuses pistes de mutation de comptes et d’injection, mais le public n’a pas besoin d’en mémoriser la liste. L’identifiant sub est la pièce qui relie l’attestation au membre stocké.", "qa": "Pourquoi ne pas inventer un numéro ? Il désignerait généralement un nouveau compte utilisateur. Le résultat recherché est de retrouver la ligne existante de l’admin, pas de créer un compte qui porte un nom convaincant. Les essais de nombres ou mots courants n’ont pas retrouvé le bon compte.", "sources": "ID_PLEASE · JOURNAL 18:39, 20:12, 20:25 · WRITEUP, SECTION 3", "gap": "Les résultats présentés sont ceux des essais documentés. Ils n’établissent pas qu’aucune autre attaque ne serait possible. Les identifiants de membres obtenus avant les remises à zéro pouvaient appartenir à d’autres participants.", "cues": ["Question 1 : demander le rôle admin ne suffit pas.", "→ Question 2 : garder le même email ne retrouve pas le compte.", "→ Question 3 : garder le même sub retrouve le même compte.", "→ Conclure : il faut le numéro exact du compte admin."]}, {"title": "ID, please — retrouver le numéro", "time": "45–60 secondes", "say": "« Un indice était sur la page d’accueil : le pied de page nommait Tech Corp Chandler et donnait une adresse Gmail. L’agent a utilisé une session Google de test pour chercher cet email via People API. La réponse lui a donné le numéro Google du compte, aussi appelé Gaia ID. Dans ce challenge, c’est le sub attendu. On peut maintenant fabriquer une attestation qui désigne le vrai compte admin. »", "details": "Le journal de solve et le write-up documentent la recherche de techcorpchandler@gmail.com et le numéro 103465053501192984574. Le script claude/gaia_lookup.py conserve la logique de recherche. Aucun cookie, en-tête d’authentification ou secret de session n’est intégré à la présentation. Le numéro abrégé sur la slide est seulement un repère visuel.", "qa": "Le numéro est-il un mot de passe ? Non : c’est un identifiant. La faille apparaît lorsque le site accepte ce numéro dans une attestation dont il ne vérifie pas l’origine. La présentation n’affirme pas qu’on peut résoudre n’importe quel email Google : elle décrit la recherche qui a fonctionné pour ce compte CTF.", "sources": "ID_PLEASE · JOURNAL 20:35, 21:25 · WRITEUP, SECTIONS 4–5", "gap": "Le journal et le write-up documentent le résultat de la recherche. Le script est conservé, mais les cookies sont hors du dépôt. Un code HTTP 401 observé plus tôt ne prouve pas à lui seul qu’un compte existe ou qu’il est social ; le succès final confirme ici le compte ciblé.", "cues": ["Montrer l’indice de la page d’accueil.", "→ Décrire une recherche avec une session Google de test.", "→ Révéler l’identifiant abrégé.", "→ Résumer le changement d’approche."]}, {"title": "ID, please — une identité usurpée", "time": "45–60 secondes", "say": "« Avec le vrai identifiant, l’attestation fabriquée retrouve le membre numéro 1, qui est administrateur. La session obtenue permet alors de lire le flag sur /api/flag. Le journal consigne le solve à 21 h 25. La leçon tient en une phrase : connaître le numéro d’un compte n’est pas une preuve qu’on en est le propriétaire. Le site devait vérifier l’attestation, et pas seulement lire le numéro qu’elle contenait. »", "details": "Le payload final porte le vrai sub et le compte email. Le rôle n’est toujours pas ajouté par le token : il vient de la ligne administrateur déjà stockée. Le write-up transcrit socialLogin avec memberId=1 et role=admin, /api/me avec le membre admin, puis /api/flag avec le flag. Il corrige l’hypothèse précédente sur /api/admin/flag : cette route renvoie 404 même comme admin.", "qa": "Qui a fait quoi ? Le write-up attribue la reconnaissance et les exclusions de pistes à plusieurs agents (pi, Codex, agy, qwen) et le déclic avec le solve final à Claude. Pourquoi tant d’impasses ? L’authentification était faible, mais il fallait d’abord trouver le sub exact ; les changements de rôles ou d’email ne désignaient pas le bon compte.", "sources": "ID_PLEASE · JOURNAL 21:25 · WRITEUP, SECTIONS 6–8", "gap": "Preuve disponible : entrée de solve et réponse transcrite dans WRITEUP.md. Aucune capture ni sortie brute finale séparée n’a été trouvée dans les fichiers inspectés. Le panneau de cette slide est une transcription du write-up, pas une capture du service. Aucun exploit n’a été relancé.", "cues": ["Présenter la chaîne finale.", "→ Révéler les résultats consignés dans le write-up.", "→ Montrer le flag et la leçon."]}, {"title": "Universal translator — retrouver un dictionnaire", "time": "45–60 secondes", "say": "« On reçoit un programme destiné à une machine inconnue. Il est composé de petits codes, mais on ne sait plus quelle action chaque code représente. La machine travaille avec une pile : elle dépose des valeurs, les copie, les déplace ou fait des calculs. Heureusement, on nous donne aussi quatre exemples et les résultats qu’ils doivent produire. Ces exemples vont servir à reconstruire le dictionnaire. »\n\nClin d’œil facultatif à dire : « Elle savait très bien ce qu’elle disait. Le problème, c’était notre niveau en machine à pile. »", "details": "L’archive contient deux README, quatre échantillons binaires et transmission.bin, un programme de 176 octets. Les codes 0x00 à 0x07 sont une permutation de huit opérations de pile ; les codes 0x10 à 0x19 sont une permutation de dix opérations arithmétiques. Les autres octets ajoutent directement une valeur à la pile. Une pile se lit depuis son sommet, la dernière valeur ajoutée. Les cases affichées sont un schéma, pas un état extrait des échantillons.", "qa": "Pourquoi ne pas essayer les instructions au hasard ? Il y a un ensemble fini de dictionnaires possibles. Les réponses connues permettent de rejeter automatiquement ceux qui ne conviennent pas. Ici, le défi est de retrouver le langage de la machine, puis d’interpréter la transmission.", "sources": "UNIVERSAL_TRANSLATOR · JOURNAL 18:48–18:51 · README DE L’ARCHIVE", "gap": "challenge.md est un modèle vide. Le journal conserve le texte fourni par l’utilisateur et les règles lues dans le README.", "cues": ["Montrer les codes dont le sens manque.", "→ Expliquer la pile en une phrase.", "→ Montrer les quatre exemples : ils servent de tests."]}, {"title": "Universal translator — voir la pile et le test", "time": "45–60 secondes", "say": "« Prenons un tout petit exemple, inventé pour comprendre. On a empilé 7, puis 3 : le 3 est donc au sommet. On cherche le sens d’une instruction, avant d’afficher le sommet. Si elle copie, on obtient 3, 3, 7 : la sortie est 3. Si elle échange les deux valeurs, le 7 passe au sommet : la sortie est 7. Si l’exemple nous dit que la sortie doit être 3, on peut éliminer “échanger”. C’est ce principe que l’agent automatise sur les vrais programmes. »", "details": "Le sommet est dessiné en haut. Copier duplique la dernière valeur ; échanger permute les deux dernières. Aucun code hexadécimal réel n’est associé à l’instruction inconnue dans ce mini-exemple. La pile et la sortie attendue sont choisies pour enseigner la mécanique, pas extraites des échantillons du challenge. Dans le mapping réellement trouvé, DUP vaut 0x03 et SWAP vaut 0x06.", "qa": "Ce test suffit-il à trouver toute la machine ? Non. L’hypothèse compatible a seulement passé un test. D’autres opérations pourraient produire la même sortie dans un cas particulier. Le solve utilise tous les exemples fournis pour départager les dictionnaires complets.", "sources": "SCHÉMA PÉDAGOGIQUE · RÈGLES DE PILE DÉCRITES DANS LE README", "gap": "Les nombres 7 et 3 et la sortie attendue 3 sont un exemple pédagogique inventé, explicitement signalé sur la slide. Ce n’est pas une trace du solve.", "cues": ["Lire la pile depuis le dessus : 3, puis 7.", "→ Si l’instruction copie, la sortie serait 3.", "→ Si elle échange, la sortie serait 7.", "→ Révéler la réponse attendue 3 : on élimine l’échange."]}, {"title": "Universal translator — les vrais tests", "time": "45–60 secondes", "say": "« Revenons au vrai challenge. L’agent commence par les actions sur la pile : copier, échanger, supprimer, émettre… Les deux premiers exemples permettent de retrouver leur correspondance avec les codes. Puis il cherche les opérations de calcul. Un exemple laisse encore 346 possibilités dans la bonne interprétation des nombres. Le dernier n’en laisse plus qu’une. Le dictionnaire peut enfin servir à lire la transmission inconnue. »", "details": "Le solve est une recherche exhaustive. stack_candidates.py teste les 8! permutations des opérations de pile contre les exemples 01 et 02. arithmetic_candidates.c teste ensuite les 10! permutations arithmétiques. L’exemple 03 laisse 428 candidats non signés ou 346 signés. Après l’exemple 04, il reste zéro candidat non signé et un seul signé. Le modèle correct utilise des entiers signés sur 64 bits pour MAX, MIN et le décalage à droite. Z3 était installé dans l’environnement, mais les solveurs conservés font de l’énumération exhaustive.", "qa": "Pourquoi préciser les nombres signés ? Une valeur peut représenter un nombre négatif. Cela change les comparaisons et certains décalages. L’agent a testé les deux conventions ; les sorties connues ont confirmé laquelle convenait. Ne pas présenter 346 comme le nombre total de toutes les possibilités initiales.", "sources": "UNIVERSAL_TRANSLATOR · JOURNAL 18:51–18:53 · CODEX/SOLVER-OUTPUT.TXT", "gap": "Schémas pédagogiques fondés sur les fichiers. Les animations ne représentent pas les temps réels du solve.", "cues": ["Deux groupes d’instructions sont résolus successivement.", "→ Les exemples 1 et 2 fixent les actions de pile.", "→ Les exemples 3 et 4 fixent les calculs : 346 puis 1.", "→ Le dictionnaire confirmé sert à lire la transmission."]}, {"title": "Universal translator — la transmission lue", "time": "45–60 secondes", "say": "« Le dictionnaire est maintenant retrouvé. Par exemple, 03 signifie copier le sommet de la pile, 04 signifie émettre une valeur, et 19 signifie additionner. L’agent utilise cette machine reconstruite pour lire transmission.bin. Elle produit des octets qui, convertis en texte, donnent le flag. La preuve est la sortie conservée du solveur. »", "details": "Le mapping complet de pile est 00=ROT, 01=TUCK, 02=OVER, 03=DUP, 04=EMIT, 05=NIP, 06=SWAP, 07=DROP. Le mapping arithmétique est 10=RSHIFT, 11=XOR, 12=LSHIFT, 13=*, 14=AND, 15=MIN, 16=MAX, 17=-, 18=OR, 19=+. Les codes sont en hexadécimal. La transmission produit les octets 42 41 32 36 7b… qui deviennent BA26{0n3_st4ck_f0rth_4ll} en ASCII. Les scripts finaux sont codex/stack_candidates.py, codex/generate_data.py et codex/arithmetic_candidates.c.", "qa": "L’agent a-t-il contacté un serveur ? Aucun serveur cible n’est spécifié dans les archives de ce challenge. Le travail documenté est local, sur les fichiers fournis. La présentation ne relance pas le solveur.", "sources": "UNIVERSAL_TRANSLATOR · CODEX/SOLVER-OUTPUT.TXT · JOURNAL 18:53", "gap": "La capture a été annotée après l’événement. La correspondance et les octets décodés sont aussi consignés dans la sortie texte conservée.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Silent beacon — le programme et le leurre", "time": "45–60 secondes", "say": "« On reçoit une copie de la mémoire d’une balise. Son programme demande un code d’activation de huit caractères hexadécimaux. Si le code est correct, il décode un enregistrement. En cherchant les textes lisibles dans le fichier, on tombe aussi sur un flag tout prêt. C’est un leurre. L’objectif est de comprendre le contrôle du code, puis de suivre le vrai décodage. »\n\nClin d’œil facultatif à dire : « Il ne manquait que le panneau : absolument pas un piège. »", "details": "Le dump beacon_flash.bin est identifié comme un firmware ESP32-C6. Le contrôle d’activation et le décodage sont dans le programme fourni. Le faux flag BA26{n0t_th15_0n3_k33p_d1gg1ng} est visible en clair à l’offset 0x19d00. La reconstruction montre que le programme en lit seulement le premier caractère pour un message de démarrage ; le chemin qui affiche UNSEALED utilise une autre zone de données.", "qa": "Le faux flag a-t-il été soumis ? Les archives ne le disent pas. Ne pas le prétendre. Avions-nous l’appareil physique ? Les sources documentent un dump et un solveur hors ligne, pas une activation sur un appareil.", "sources": "SILENT_BEACON · JOURNAL 18:45, 18:49 · BACKFILL 20:57", "gap": "Le texte complet du challenge, les commandes exactes de désassemblage et une éventuelle activation réelle ne sont pas conservés. Le schéma mémoire est pédagogique, pas une carte à l’échelle.", "cues": ["Présenter le dump de mémoire.", "→ Présenter le contrôle du code.", "→ Montrer le leurre en clair.", "→ Dire ce qui fera réellement preuve."]}, {"title": "Silent beacon — le contrôle d’activation", "time": "45–60 secondes", "say": "« Le contrôle est entièrement dans le programme. Il prend deux textes lisibles dans le dump et calcule deux nombres, des empreintes. Il les combine ensuite suivant une recette fixe. Le résultat est B80FEF82. C’est à ce nombre qu’il compare le code fourni. L’agent n’a pas essayé tous les codes : il a refait le calcul qu’il venait de lire. »", "details": "Les textes sont LilyGO T7-C6 et BA26-BEACON-01. Le contrôle applique FNV-1a 32 bits à chacun. Les hashes conservés sont 56ea3ff6 pour LilyGO T7-C6 et cd1014a9 pour BA26-BEACON-01. Le code attendu est rotl32(56ea3ff6,7) XOR cd1014a9 = B80FEF82. Ces valeurs viennent de la sortie sauvegardée, pas d’un recalcul pour la présentation. L’opération de rotation déplace les bits en boucle ; XOR combine les bits. Les deux termes techniques restent facultatifs à l’oral.", "qa": "Qu’est-ce qu’une empreinte ? Ici, un nombre obtenu de façon déterministe à partir d’un texte. Le point important n’est pas de retenir FNV, mais que le texte et la recette sont connus. Une tentative initiale a inversé les deux hashes et donné DEE06B10 : leur ordre est donc essentiel.", "sources": "SILENT_BEACON · CODEX/SOLVE.PY · CLAUDE/OUT-03-SOLVE.TXT", "gap": "La comparaison affichée est un schéma de la logique analysée. Les archives ne prouvent pas qu’un code ait été saisi sur un appareil ou un service. L’erreur initiale est consignée, mais sa sortie n’a pas été conservée.", "cues": ["Les ingrédients du calcul sont les deux textes du dump.", "→ Le programme les transforme en deux empreintes.", "→ Il les combine pour obtenir le code attendu.", "→ Le contrôle compare le code fourni à cette réponse."]}, {"title": "Silent beacon — deux calculs distincts", "time": "45–60 secondes", "say": "« Il faut bien distinguer deux choses. Le premier calcul sert à vérifier le code d’activation. Le second utilise les mêmes empreintes pour générer une suite de nombres. On combine cette suite avec les octets chiffrés du dump, un octet à la fois, et le texte devient lisible. Le code attendu n’est donc pas simplement une clé qu’on applique au fichier : le solveur reproduit aussi cette deuxième recette. »", "details": "Le décodeur utilise les deux hashes comme un état initial 64 bits de xorshift, avec les décalages 13, 7 et 17. Le hash de LilyGO T7-C6 est le mot haut ; celui de BA26-BEACON-01 est le mot bas. À chaque étape, le programme produit un nouvel état et combine son octet bas par XOR avec un octet des 31 octets stockés à l’adresse 0x42039d40. La représentation par des points est symbolique : elle n’affiche pas des valeurs de flux calculées.", "qa": "Pourquoi le bon code ne suffit-il pas à expliquer le flag ? Il explique le contrôle d’accès, mais il faut aussi savoir comment le contenu est transformé pour justifier le texte retrouvé. Ici, toutes les données et opérations nécessaires sont présentes dans le dump ; le solveur peut donc les reproduire hors ligne.", "sources": "SILENT_BEACON · CODEX/SOLVE.PY · JOURNAL 18:49, BACKFILL 20:57", "gap": "Le schéma distingue deux usages réels des hashes ; il n’est pas une capture d’exécution. Aucun décodeur n’a été relancé pour préparer cette slide.", "cues": ["Les deux empreintes servent au contrôle déjà expliqué.", "→ Elles servent aussi à produire une suite pour décoder.", "→ Combiner cette suite avec les 31 octets permet de lire le texte.", "→ Le solveur reproduit les deux étapes."]}, {"title": "Silent beacon — la preuve du décodage", "time": "45–60 secondes", "say": "« Le solveur retrouve le code attendu et décode l’enregistrement. Cette fois, le flag vient bien du chemin de succès du programme, et il est enregistré dans la sortie du solveur. On sait donc expliquer comment il a été obtenu. C’est la différence avec le faux flag trouvé en clair : l’analyse relie le résultat au mécanisme réel du challenge. »", "details": "codex/solve.py lit le dump, récupère les textes d’identité, calcule les hashes et le code, puis refait le xorshift et les XOR sur les 31 octets. La sortie conservée indique activation code=B80FEF82 et record=BA26{x0rsh1ft_s34ls_th3_b34c0n}. Les étapes techniques détaillées sont dans le journal original de Codex et dans la reconstruction à partir du désassemblage conservé.", "qa": "Est-ce une preuve de déverrouillage matériel ? Non : la preuve documentée est le calcul et le décodage hors ligne. Le journal ne conserve aucune trace d’une saisie du code sur un appareil ou un service. Ce que l’on peut affirmer est que le solveur reproduit la logique analysée et retrouve le résultat journalisé.", "sources": "SILENT_BEACON · CLAUDE/OUT-03-SOLVE.TXT · JOURNAL 18:49", "gap": "La capture de sortie a été produite lors du backfill à partir d’une reproduction hors ligne. Elle concorde avec le code d’activation et le flag consignés par Codex pendant le solve.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Wrong path — sortir du dossier", "time": "45–60 secondes", "say": "« FileVault nous laisse déposer puis lire des fichiers. Le serveur doit rester dans le dossier de notre compte. Regardons la requête documentée : on demande “deux fois point point slash, challenge.db”. Le serveur l’ajoute au chemin de notre compte. Le premier “../” remonte de notre compte vers uploads ; le second remonte vers app. La cible devient donc /app/challenge.db : la base de comptes. Une autre route, /download, bloquait bien cette sortie. L’agent a utilisé /raw. »\n\nClin d’œil facultatif à dire : « On avait accès à notre tiroir. Deux points et un slash plus tard, on visitait le meuble. »", "details": "La requête GET /raw?filename=../../challenge.db et la racine /app/uploads/<username>/ figurent dans JOURNAL.md, sections App et Exploitation. Le journal décrit open(os.path.join(UPLOAD_FOLDER,user,filename)) sans assainissement pour /raw et /view, contre send_from_directory pour /download. La résolution présentée illustre la sémantique de ../ ; elle n’est pas une réponse HTTP récupérée à nouveau. Avant la base, la lecture de ../../app.py avait confirmé son emplacement. /etc/passwd a servi de preuve de traversée. L’essai ....// a échoué ; ../ et sa forme encodée ont fonctionné selon les notes.", "qa": "Pourquoi os.path.join ne protège-t-il pas ? Il compose un chemin ; le mécanisme documenté n’impose pas ensuite que le fichier final reste sous le dossier autorisé. On ne peut pas déduire de ce solve que toutes les routes de l’application étaient vulnérables : le contraste /download versus /raw est essentiel.", "sources": "WRONG_PATH/JOURNAL.MD · APP, EXPLOITATION, SOLVED 20:07", "gap": "Aucune capture de l’interface web ni requête/réponse brute n’a été conservée. Les chemins et la requête sont transcrits du journal ; le nom de compte est remplacé par un repère générique.", "cues": ["Lire la requête et nommer le dossier autorisé.", "→ Montrer le chemin construit et le sens de ../.", "→ Montrer le fichier final hors du dossier.", "→ Comparer la route sûre et la route vulnérable."]}, {"title": "Wrong path — le faux flag", "time": "45–60 secondes", "say": "« La base contient un mot de passe qui ressemble à un flag. L’agent pense d’abord avoir fini, puis corrige cette conclusion : c’était un piège. Les vrais identifiants administrateur sont dans la même base. Une fois connecté comme admin, il voit un fichier qui indique que le vrai flag a été caché dans un labyrinthe. »", "details": "Le journal contient une correction explicite : la chaîne de type BA26-dftwp-… est un leurre, pas le résultat final. La lecture de /proc/self/environ a révélé SECRET_KEY et confirmé la localisation des identifiants. Le compte admin de challenge.db a permis l’accès à /dashboard, où figuraient flag.txt et flag.maze. Le solve final utilise les identifiants ; il ne faut pas inventer une falsification de session avec SECRET_KEY.", "qa": "Comment sait-on que le premier flag était faux ? Le journal le corrige explicitement et le résultat réel est conservé dans claude/out-01.txt. La présentation suit cette correction, pas le premier résumé obsolète.", "sources": "WRONG_PATH · CLAUDE · JOURNAL, CORRECTION ET RECONSTRUCTION", "gap": "Le journal reconstitue l’ordre général des étapes après l’événement. Il n’existe pas de traces HTTP permettant de dater chaque action précisément.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Wrong path — comprendre BFS", "time": "45–60 secondes", "say": "« Le labyrinthe comporte plus de quarante mille cases : le lire à l’œil serait laborieux. Le programme utilise une recherche en largeur. Il garde une file de cases à explorer. Quand il visite une case, il ajoute ses voisins accessibles qu’il n’a pas encore vus, en mémorisant d’où ils viennent. Dès que la sortie est trouvée, il remonte ces liens pour reconstruire le chemin. Seules les lettres sur ce chemin seront gardées. »", "details": "claude/solve.py lit la grille, repère les deux caractères >, puis initialise prev={start:None} et q=deque([start]). Les quatre voisins sont testés ; une case est admissible si elle reste dans la grille et n’est pas un #. Le dictionnaire prev sert à la fois de marqueur de visite et de lien vers le prédécesseur. Le solveur s’arrête en atteignant la sortie, reconstruit puis renverse le chemin, et retire les murs, espaces et portes avant de joindre les lettres. Le pseudocode de la slide simplifie exactement ces opérations.", "qa": "Pourquoi conserver le prédécesseur ? Une liste de cases visitées ne donne pas directement la route finale : elle inclut aussi des branches inutiles. Les liens permettent de repartir de la sortie et de retrouver la suite exacte des cases. Aucun besoin d’expliquer des graphes formels pour suivre cette idée.", "sources": "WRONG_PATH/CLAUDE/SOLVE.PY · FILE DE CASES, PREV, RECONSTRUCTION", "gap": "Le pseudocode est une traduction pédagogique du solveur conservé, pas une trace de son exécution. La recherche n’a pas été relancée pour produire la présentation.", "cues": ["Lire les cinq lignes de l’algorithme sans détailler Python.", "→ Expliquer pourquoi chaque case garde un prédécesseur.", "→ Revenir de la sortie vers l’entrée.", "→ Garder les lettres de la route, pas celles des branches."]}, {"title": "Wrong path — le labyrinthe", "time": "45–60 secondes", "say": "« Le fichier est un labyrinthe en texte : des murs, des couloirs et des lettres. Le solveur explore les passages depuis l’entrée jusqu’à la sortie. Il conserve ce chemin, puis lit les caractères qui s’y trouvent. Ensemble, ils forment le vrai flag. Le dessin vert est un rendu du chemin retrouvé à partir du fichier conservé. »", "details": "Le labyrinthe mesure 201 × 201. Les deux portes sont en (ligne 1, colonne 0) et (ligne 199, colonne 200). claude/solve.py utilise une recherche en largeur, ou BFS, puis remonte les prédécesseurs pour reconstruire le chemin. La sortie sauvegardée indique une longueur de 2 783 positions. Le flag complet est BA26{tHis_Is_a_rEally_loNG_flag_ThAt_is_Very_DiFFicult_to_gUess_bUT_you_cAn_find_It_in_tHE_mAze}.", "qa": "Qu’est-ce qu’une recherche en largeur ? Elle visite d’abord les cases voisines, puis leurs voisines, couche par couche. Le public peut retenir « explorer les couloirs en conservant d’où l’on vient ». Le chemin vert représente le résultat conservé, pas une animation de l’exécution d’origine.", "sources": "WRONG_PATH/CLAUDE/SOLVE.PY · OUT-01.TXT · RENDER_MAZE.PY", "gap": "Le dessin a été créé après l’événement à partir du labyrinthe local. La chaîne sur la slide est volontairement abrégée ; la preuve et les notes donnent le résultat complet.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Peak privilege — le défi", "time": "45–60 secondes", "say": "« Ce système décide des droits à partir d’une image de badge. Il classe chaque image comme employé, invalide ou administrateur. Pour obtenir le flag, il faut que son score ADMIN atteigne 99,5 %. On ne possède pas le modèle, mais le service donne ses scores. C’est cette information qui va guider les modifications de l’image. »", "details": "L’entrée est une image RGB 256 × 176. Le traitement connu découpe un carré 96 × 96, le passe en niveaux de gris puis moyenne des blocs 3 × 3 pour obtenir une grille 32 × 32. L’agent peut donc contrôler 1 024 valeurs via des blocs de pixels. Les poids du modèle ne sont pas fournis. Le badge employé initial a un score EMPLOYEE proche de 1 et ADMIN d’environ 2,3 × 10⁻²³.", "qa": "Est-ce une reconnaissance de carte d’identité ? Les archives décrivent un scanner artificiel NeuralBadge de CTF avec trois classes. Ne pas extrapoler ce résultat à un produit réel. Le score renvoyé est une sortie du modèle, pas une garantie de probabilité réelle.", "sources": "PEAK_PRIVILEGE/JOURNAL.MD · SETUP · CLAUDE/EXTRACTED/PLAYER/PREPROCESS.PY", "gap": "La description vient du journal, car challenge.md est un modèle vide. L’image employé est un fichier fourni ; le scanner dessiné est une illustration.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Peak privilege — contrôler l’entrée", "time": "45–60 secondes", "say": "« Avant de chercher un badge gagnant, l’agent lit le traitement appliqué à l’image. Le modèle ne voit pas toute la carte : seulement ce carré. Il est converti en gris, puis chaque bloc de trois pixels sur trois devient une valeur moyenne. Cela donne une grille de 32 sur 32. Si on met neuf pixels identiques dans un bloc, on choisit exactement la valeur de la case correspondante. L’agent peut donc piloter toutes les entrées du modèle. »", "details": "preprocess.py donne BADGE_SIZE=(256,176), PATTERN_BOX=(32,48,128,144) et une conversion de luminance 0,299R+0,587G+0,114B, suivie de reshape(32,3,32,3).mean(axis=(1,3)). Régler R=G=B=k sur un bloc donne k/255, soit 256 niveaux contrôlables par case. claude/work/badge.py fait l’opération inverse pour produire un PNG : grid_to_png agrandit la grille et la place dans le carré. Le journal rapporte un écart maximum de 1,2×10⁻⁷ lors du test aller-retour. Le cadre et le recadrage montrés utilisent les coordonnées exactes de la spécification ; la grille de droite est schématique.", "qa": "Pourquoi cette étape compte-t-elle ? Modifier du texte ou des pixels hors du carré serait inutile : ils sont éliminés avant le modèle. Les bonnes dimensions d’image ne suffisent pas ; il faut comprendre ce qui est effectivement transmis au classifieur. Le contrôle est quantifié sur 256 niveaux, pas sur des réels de précision infinie.", "sources": "PEAK_PRIVILEGE/CLAUDE/EXTRACTED/PLAYER/PREPROCESS.PY · CLAUDE/WORK/BADGE.PY", "gap": "L’image est le badge fourni. Le recadrage et le cadre sont des explications visuelles du code fourni ; la grille 32 × 32 est représentée schématiquement, sans prétendre afficher ses 1 024 valeurs mesurées.", "cues": ["Pointer le carré lu dans le badge.", "→ Montrer ce qui est recadré puis moyenné.", "→ Expliquer comment neuf pixels identiques contrôlent une case.", "→ Conclure : toute l’entrée utile est contrôlable."]}, {"title": "Peak privilege — plus chaud, plus froid", "time": "45–60 secondes", "say": "« L’agent part du vrai badge employé, car du bruit aléatoire donnait surtout INVALID. À chaque tour, il choisit vingt variations. Pour chacune, il teste le badge modifié dans un sens et dans le sens contraire : quarante images au total. Si un sens rapproche davantage de ADMIN, la différence des scores indique une direction utile. Il combine les vingt indications, modifie le badge et recommence. C’est “plus chaud, plus froid”, mais mesuré et automatisé. »", "details": "Le solveur nes.py construit x+sigma·eps[k] et x−sigma·eps[k] pour chacune des 20 perturbations gaussiennes. Son objectif est log(pADMIN) − log(max(pEMPLOYEE,pINVALID)). La différence des deux objectifs pondère la perturbation ; leur moyenne estime un gradient. Il normalise ce gradient, applique un pas de taille lr, puis borne x dans [0,1]. La conversion en PNG quantifie à 256 niveaux. Le meilleur score ADMIN et sa grille sont sauvegardés. Le journal rapporte deux phases : sigma=0,06 et lr=0,08, puis lr=0,28. Le script vérifie aussi le badge courant hors du lot de variations.", "qa": "Choisit-il simplement le meilleur badge du lot ? Non : il estime une direction à partir des paires, puis construit une nouvelle image. Les vingt paires aident à agréger des signaux bruités. « Plus ADMIN » simplifie la comparaison : l’objectif tient également compte de la classe concurrente la plus forte. Toutes les étapes ne sont pas nécessairement meilleures que la précédente.", "sources": "PEAK_PRIVILEGE/CLAUDE/WORK/NES.PY · SCORE, PAIRES ±EPS, GRADIENT, MISE À JOUR", "gap": "Les deux variantes sont représentées par leur rôle, sans image ni score inventé. Le journal conserve un résumé des essais, pas la série complète des retours HTTP.", "cues": ["Expliquer le départ depuis un badge déjà reconnu.", "→ Comparer les deux sens d’une même variation.", "→ Combiner les directions et mettre à jour le badge.", "→ Répéter la boucle jusqu’à l’acceptation."]}, {"title": "Peak privilege — le badge accepté", "time": "45–60 secondes", "say": "« Le badge final est visuellement étrange. Pourtant, le journal rapporte un score ADMIN de 99,6 %, au-dessus du seuil de 99,5 %, puis l’accès accordé et le flag. L’image gagnante a été conservée. La leçon de ce challenge est que le modèle donne à l’attaquant une mesure qui l’aide à fabriquer une entrée acceptée. »\n\nClin d’œil facultatif à dire : « Pour la photo du badge, le modèle a clairement des critères différents des ressources humaines. »", "details": "Le journal rapporte environ 113 appels par lots de 40 images pour l’ensemble de la résolution ; ces nombres restent approximatifs. La seconde phase atteint le seuil après environ 53 itérations. Le badge est claude/work/admin_badge.png, avec la grille gagnante best_grid.npy. Le solveur final est nes.py. Le résultat et le flag sont consignés dans la section SOLVED.", "qa": "La capture prouve-t-elle à elle seule le score ? Non : elle montre le badge gagnant. Le score, l’accès accordé et le flag viennent du journal. Aucun log brut des réponses du service n’est gardé ; la présentation le dit explicitement dans la provenance.", "sources": "PEAK_PRIVILEGE/JOURNAL.MD · SOLVED · CLAUDE/WORK/ADMIN_BADGE.PNG, BEST_GRID.NPY", "gap": "Les notes originales sont non datées ; les horaires de la reconstruction viennent des dates de fichiers. Le score de 0,996 est rapporté dans le journal, sans réponse HTTP brute conservée.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Rucher — les deux fichiers", "time": "45–60 secondes", "say": "« On dispose de dix secondes de signal radio et du programme d’une balance. La résolution comporte trois couches. D’abord, transformer les ondes en octets : c’est du décodage radio. Ensuite, retrouver la clé Zigbee pour lire les rapports : c’est le chiffrement du réseau. Enfin, ces rapports contiennent des fragments encore chiffrés par l’application. Le firmware nous explique cette dernière règle, liée à l’identité de la balance. »\n\nClin d’œil facultatif à dire : « Pour un challenge nommé Rucher, le vrai buzz venait de la balance. »", "details": "La capture SigMF de 80 Mo contient des échantillons ci8 à 4 MS/s, centrés sur 2 475 MHz. Le journal identifie IEEE 802.15.4 canal 25 et Zigbee. Le dump balance_flash.bin est un firmware ESP32-C6 partiel. Ses chaînes nomment Zigbee et la clé par défaut ; sa zone NVS est vierge, donc il ne contient pas la clé réseau provisionnée de la balance observée. Le journal attribue l’ensemble du solve à Claude. Les trois couches de la slide regroupent la démodulation, la sécurité Zigbee et la protection applicative RC4 ; elles ne prétendent pas représenter toutes les sous-couches officielles du protocole.", "qa": "Pourquoi les deux fichiers sont-ils nécessaires ? La radio apporte les échanges d’appairage, les fragments et l’identité de l’appareil. Le firmware permet de comprendre le protocole et la fabrication de la dernière clé. Il n’y a pas de flag prêt à être lu dans ce dump de fabrication.", "sources": "RUCHER/JOURNAL.MD · SECTIONS 0–4 · RUCHER.SIGMF-META · BALANCE_FLASH.BIN", "gap": "Le diagramme est une vue pédagogique des étapes du solve. La chronologie a été reconstruite à partir des fichiers ; le dump est tronqué et ne contient pas des partitions complètes hors de sa taille.", "cues": ["Distinguer le signal radio du programme embarqué.", "→ Montrer le chiffrement du réseau comme une deuxième couche.", "→ Montrer la protection propre à l’application.", "→ Annoncer que chaque étape a son propre test de vérification."]}, {"title": "Rucher — des ondes aux paquets", "time": "45–60 secondes", "say": "« Au début, on n’a que des ondes enregistrées. L’agent reconnaît le protocole Zigbee et écrit un décodeur. Il compare le signal aux motifs attendus pour retrouver les nombres envoyés. Les paquets possèdent un contrôle d’erreur : c’est un bon moyen de vérifier le décodage. Résultat : les 42 paquets passent ce contrôle. On peut maintenant analyser les messages. »", "details": "Les scripts decode154.py et extract_all.py détectent les salves et emploient un filtre adapté complexe aux motifs O-QPSK/DSSS. Le suréchantillonnage ×4 améliore la précision. Le FCS CRC-16 sert à confirmer les conventions de modulation et les octets. Le résultat est enregistré dans claude/rucher.pcap, avec 42 salves décodées et des FCS valides. La capture comprend l’association puis des rapports périodiques.", "qa": "Le contrôle d’erreur déchiffre-t-il le message ? Non. Il confirme que les bits radio ont été lus correctement. Le contenu peut encore être chiffré. C’est pour cela que le décodage et le déchiffrement sont deux étapes distinctes.", "sources": "RUCHER/CLAUDE/DECODE154.PY · EXTRACT_ALL.PY · JOURNAL.MD, SECTION 2", "gap": "L’onde dessinée est une illustration du signal, pas une courbe mesurée. La quantité 42/42 vient du journal et du fichier de paquets conservé.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Rucher — la clé réseau", "time": "45–60 secondes", "say": "« La balance reçoit sa clé réseau quand elle rejoint la passerelle. L’échange est dans notre capture. La clé n’est pas envoyée en clair : le message est protégé par une clé de transport, dérivée d’une clé par défaut connue. L’agent applique cette dérivation, ouvre le message Transport-Key et vérifie son contrôle d’authenticité. Il dispose alors de la clé réseau. Elle ouvre les rapports et révèle six fragments, qui ont encore une protection applicative. »", "details": "Le message APS Transport-Key est protégé avec une clé de transport dérivée de ZigBeeAlliance09 par le hachage Zigbee AES-MMO avec l’octet 0x00. Il ne faut pas dire que la clé par défaut est directement appliquée au paquet sans cette dérivation. AES-CCM* permet de déchiffrer et de vérifier le MIC. La clé réseau récupérée est b8d8e46f82f99446568d2d30e9512c16. Les rapports NWK vérifiés contiennent six fragments indexés de 0 à 5, totalisant 46 octets.", "qa": "La clé est-elle envoyée en clair ? Non : elle est chiffrée, mais sa protection dérive d’une clé par défaut connue. Pourquoi faut-il capturer l’appairage ? Dans ce solve, c’est l’échange conservé qui fournit la clé réseau nécessaire pour lire les rapports.", "sources": "RUCHER/CLAUDE/SOLVE_FINAL.PY · ZB_KEYED_HASH, CCM_STAR, TRANSPORT-KEY", "gap": "Les algorithmes de dérivation et de chiffrement sont nommés dans les notes. La slide expose la dépendance entre les clés sans prétendre qu’une clé en clair circulait sur la radio.", "cues": ["La distribution de clé a été enregistrée.", "→ Dériver la clé de transport depuis la clé par défaut.", "→ Ouvrir le message et vérifier son authenticité.", "→ Utiliser la clé réseau pour lire les six fragments."]}, {"title": "Rucher — la couche liée à l’appareil", "time": "45–60 secondes", "say": "« Le firmware révèle comment est fabriquée la dernière clé. Elle concatène l’identifiant radio de la balance, le mot “propolis” et le numéro du fragment. L’identifiant, ici une adresse EUI-64 de huit octets, est visible dans la capture. Il fait que deux balances n’utilisent pas la même clé, mais il ne constitue pas un secret pour l’observateur. L’agent reconstruit donc chaque clé, applique RC4 normalement et assemble les six morceaux. Il ne s’agit pas d’une cassure mathématique de RC4. »", "details": "L’algorithme reconnu est RC4, réinitialisé pour chaque fragment. La clé exacte est EUI-64 en ordre little-endian, suivie des octets de “propolis”, puis d’un octet d’index. L’EUI-64 de la balance est 40:4c:ca:ff:fe:46:87:c4, soit c48746feffca4c40 en little-endian. Le solveur final claude/solve_final.py prend le pcap, récupère la clé réseau, déchiffre les rapports et la couche RC4, puis concatène les fragments. La sortie conservée confirme le flag affiché.", "qa": "L’identité de la balance est-elle un secret ? Elle est observable dans la capture. Ici, elle personnalise le chiffrement, mais elle ne suffit pas à garder le contenu secret une fois le mécanisme compris. Pourquoi le firmware seul ne donne-t-il pas le flag ? Il manque les messages de cette balance et son identité observée.", "sources": "RUCHER/CLAUDE/SOLVE_FINAL.PY · CLÉ PAR FRAGMENT · OUT-01-SOLVE.TXT", "gap": "Le résultat montré provient d’une reproduction hors ligne conservée lors du backfill. Cette présentation n’a relancé aucun solveur. Les premiers journaux d’outils et l’essai initial de démodulation ne sont pas conservés.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Driver radio — le message et sa preuve", "time": "60–75 secondes", "say": "« Le défi demande d’envoyer exactement “Box Box Box!” aux 22 pilotes. Mais le programme exige aussi une signature valable pour le pilote choisi. La clé privée permet de produire cette signature ; la clé publique permet de la vérifier. Les clés publiques sont dans le programme reçu. Il manque donc le secret qui permet de signer. Une signature ne cache pas le message : elle permet ici de vérifier qu’il est autorisé. »", "cues": ["Poser l’objectif : un ordre accepté par 22 pilotes.", "→ Expliquer clé privée et signature.", "→ Expliquer le contrôle avec la clé publique.", "→ Nommer le secret manquant."], "details": "Le binaire fourni est un ELF x86-64 avec symboles et informations de debug. Les fonctions pertinentes sont menu_spy, menu_send, ecdsa_sign et ecdsa_verify. menu_send vérifie la signature ECDSA P-256 et marque le pilote si le texte est exactement “Box Box Box!”. Le programme affiche le flag lorsque les 22 indicateurs sont activés. Les tableaux PILOT_QX et PILOT_QY contiennent les coordonnées des 22 clés publiques.", "qa": "Pourquoi lire une clé publique n’est-il pas déjà une faille ? Elle est faite pour être connue. On doit pouvoir vérifier une signature sans pouvoir retrouver la clé privée. C’est une autre faiblesse qui permet ici de franchir cette séparation.", "sources": "driver_radio/JOURNAL.md : entrées 20:00 et 20:05 ; claude/send_exploit.py.", "gap": "challenge.md est aussi un modèle vide dans driver_radio. Le contexte de la slide vient du journal et de la logique documentée du binaire. Le dessin de radio est une illustration pédagogique, pas une capture du programme."}, {"title": "Driver radio — un hasard trop petit", "time": "60–75 secondes", "say": "« La signature utilise un autre secret, temporaire : le nonce. Ce n’est pas la clé privée. Dans ce programme, il n’a que 255 valeurs possibles. Le menu Spy montre une signature, même si le message est chiffré. Une partie de cette signature dépend du nonce. L’agent peut donc essayer toutes les valeurs et comparer. Cette recherche retrouve le nonce ; elle ne donne pas encore à elle seule la clé du pilote. »", "cues": ["Distinguer le nonce de la clé privée.", "→ La signature donne une valeur à comparer.", "→ Tous les candidats peuvent être essayés.", "→ Dire ce qui manque encore."], "details": "Le journal donne k = (rand() % 255) + 1 et r = (k·G).x mod n. G est le point de base de la courbe ; n est son ordre. Le solveur prépare un dictionnaire des valeurs de r associées aux 255 k possibles. Ce calcul est fait une fois, puis r sert de clé de recherche. Le message est montré chiffré en AES-CTR, mais la signature (r,s) reste visible. La faille exposée concerne la génération du nonce ECDSA.", "qa": "Est-ce une recherche de 255 clés privées ? Non. La grille représente seulement les 255 nonces permis par cette implémentation. La clé privée reste à récupérer avec la signature et le message. La courbe P-256 ne possède évidemment pas seulement 255 clés. Le nombre gagnant n’est pas simulé sur cette slide.", "sources": "driver_radio/JOURNAL.md : 20:05 et 20:15 ; claude/recover.py, dictionnaire rk ; screenshots/claude-02-nonce-vuln.annotated.png.", "gap": "Le fichier de décompilation conservé est vide. La région vulnérable est documentée dans le journal et la capture annotée ; le désassemblage complet n’a pas été gardé. Cette capture est une preuve documentaire, pas du code extrait à nouveau pour cette présentation."}, {"title": "Driver radio — le déclic des messages", "time": "60–75 secondes", "say": "« Le nonce est retrouvé, mais le texte signé reste caché. La première idée était de reproduire le hasard à partir de l’heure. Le déclic a été de regarder les messages : ils viennent de quelques modèles. Un mode moteur, un plan, un tour d’arrêt… Les variables ont peu de valeurs possibles. L’agent a donc énuméré les messages, environ 800 par pilote. Chaque message devient une hypothèse à tester. »", "cues": ["Expliquer brièvement la piste de l’horloge.", "→ Lire un modèle de phrase et ses variables.", "→ Faire apparaître le nombre limité de candidats.", "→ Résumer ce que le déclic simplifie."], "details": "Le journal décrit environ 800 messages par pilote, issus de huit types de messages et de petites plages de valeurs, volontairement élargies. recover.py conserve des candidats supplémentaires pour couvrir ces plages. Le fichier permet de vérifier les formats affichés. Le nom du pilote fait partie du message : “[pilote]” sur la slide est une abréviation pédagogique. Les chaînes exactes incluent le nom complet.", "qa": "L’agent a-t-il cassé AES ? Le solve final n’en a pas besoin : il énumère les textes plausibles et vérifie la clé privée résultante contre la clé publique connue. Pourquoi abandonner l’horloge ? La nouvelle approche élimine la dépendance à la seed, à l’heure et à l’alignement des appels de rand().", "sources": "driver_radio/JOURNAL.md : 20:07, 20:12, 20:15 ; claude/recover.py, fonction enum().", "gap": "La validation locale envisagée pour la première piste a été bloquée par l’absence de libcrypto.so.3 pour x86-64. Les exemples montrés sont des modèles tirés du solveur, pas une transcription d’un échange précis avec un pilote."}, {"title": "Driver radio — calculer puis confirmer", "time": "60–75 secondes", "say": "« On combine trois choses : la signature observée, le nonce retrouvé, et un message possible. La relation mathématique de la signature permet de calculer une clé privée candidate. Mais on ne la croit pas sur parole. On calcule sa clé publique et on vérifie qu’elle est bien celle du pilote. Si elle ne correspond pas, on essaie un autre message. Le solveur a ainsi retrouvé et confirmé les 22 clés privées. »", "cues": ["Réunir les trois informations.", "→ Calculer une candidate.", "→ Expliquer le test et ses deux issues.", "→ Annoncer les 22 confirmations."], "details": "Équation ECDSA documentée : s = k⁻¹(z + r·d) mod n. Multiplier par k, soustraire z, puis multiplier par l’inverse de r donne d = r⁻¹(s·k − z) mod n. z = SHA256(message). r⁻¹ désigne l’inverse multiplicatif modulo n, pas un inverse décimal. d est un entier privé, G le point de base, Q la clé publique. Le test d·G = Q vérifie la candidate. Dans recover.py, il correspond à eqpt(mulG(d), Q).", "qa": "Pourquoi faut-il deviner le message ? Sans z, le calcul de d n’est pas déterminé. Pourquoi plusieurs signatures ont-elles été récupérées ? Le journal indique dix observations par pilote, soit 220 signatures ; le solveur parcourt les signatures jusqu’à trouver une clé confirmée. Il ne faut donc pas dire que l’opération historique n’a demandé qu’une seule observation par pilote.", "sources": "driver_radio/JOURNAL.md : 20:15–20:16 ; claude/recover.py, lignes de récupération et comparaison ; claude/crypto.py.", "gap": "Cette présentation lit les scripts et les résultats conservés. Elle ne recalcule ni les clés ni les signatures. Les clés privées n’ont pas besoin d’être affichées pour expliquer ou démontrer le résultat."}, {"title": "Driver radio — 22 ordres acceptés", "time": "60–75 secondes", "say": "« Avec les clés retrouvées, l’agent peut signer “Box Box Box!” pour chacun des 22 pilotes. Il vérifie ces signatures localement, puis les envoie dans une nouvelle connexion. La réponse conservée montre les 22 acceptations et le flag. La conclusion est précise : ici, un nombre temporaire trop facile à deviner et des messages prévisibles ont permis de retrouver les clés de signature. »\n\nClin d’œil facultatif à dire : « Imaginez la tête des mécaniciens : vingt-deux pilotes arrivent en même temps ! »", "cues": ["Annoncer le résultat global.", "→ Montrer la capture conservée.", "→ Reprendre les trois grandes étapes.", "→ Donner la leçon sans généraliser à toutes les signatures."], "details": "Chaîne de fichiers historique : harvest.py → sigs.json → recover.py → priv.json → send_exploit.py → final_resp.txt. Les clés sont statiques entre connexions selon le journal ; l’agent a ainsi pu récupérer hors ligne puis signer dans une nouvelle connexion. Le flag enregistré est BA26{T0t0_1ts_C4ll3d_4_M0t0r_R4c3_N0t_S3cur3_Crypt0}.", "qa": "Est-ce une cassure générale d’ECDSA ? Les archives montrent une exploitation de cette implémentation : nonce de 1 à 255 et messages énumérables. Ne pas généraliser le résultat à toutes les implémentations ou à tous les usages de signatures.", "sources": "driver_radio/JOURNAL.md : 20:19–20:20 ; claude/final_resp.txt ; claude/send_exploit.py ; screenshots/claude-01-flag.annotated.png.", "gap": "L’annotation de la capture a été ajoutée après l’événement. Le résultat est corroboré par final_resp.txt et le journal de solve. Les timings d’animation n’indiquent pas la vitesse réelle d’exploitation."}, {"title": "Tapo — le défi", "time": "45–60 secondes", "say": "« Une caméra, c’est aussi un petit ordinateur. Elle conserve des programmes, des réglages et des fichiers dans sa mémoire. Voici le matériel photographié pendant le travail. Le but du challenge est de retrouver un message caché. La caméra surveillait le jardin ; pour une fois, c’est elle qu’on regarde de près. »", "details": "Le support identifie une Tapo C500 2.0 et un dump de 8 Mio. Le firmware est le logiciel embarqué. Un dump est une copie brute de la mémoire flash. La photographie est extraite du PowerPoint fourni, sans modification de l’original.", "qa": "Un dump est-il une vidéo ? Non : ici, c’est une copie de la mémoire qui contient le logiciel et les données de l’appareil.", "sources": "TAPO · POWERPOINT FOURNI, SLIDES 1–4", "gap": "Photographie fournie par l’utilisateur. Le dump lui-même n’est pas joint à cette demande ; aucune acquisition ou exécution réalisée pour la présentation.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Tapo — le matériel et le dump", "time": "45–60 secondes", "say": "« La pince et les fils relient la carte à un adaptateur, qui sert d’intermédiaire avec l’ordinateur. Le support décrit une lecture de la mémoire avec un CH347 en mode SPI et flashrom. Le résultat est un fichier de huit mébioctets. Toute la suite consiste à comprendre cette copie. Beaucoup de câbles, mais une seule pièce jointe à analyser. »", "details": "SPI est un mode de communication entre composants électroniques. L’adaptateur et le montage sont visibles dans les photographies. La lecture CH347/SPI/flashrom est rapportée par les notes du PowerPoint. Nous n’en déduisons aucun brochage et ne proposons pas de procédure matérielle à partir des photos.", "qa": "Pourquoi travailler sur une copie ? Elle permet de relire et comparer les octets hors ligne. Cela ne dit pas si le montage était lui-même sûr ou reproductible : ce n’est pas vérifié ici.", "sources": "TAPO · PHOTOS ET NOTES DU POWERPOINT, SLIDES 3–5", "gap": "Les quatre photos sont fournies par l’utilisateur. Leur ordre sur les slides est pédagogique, pas une datation du travail matériel.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Tapo — distinguer compression et chiffrement", "time": "45–60 secondes", "say": "« Chercher BA26 dans la mémoire est un premier réflexe raisonnable. Le support rapporte plusieurs recherches sans résultat. Il y a deux couches à distinguer. La compression range les fichiers en prenant moins de place : on doit les décompresser. Le chiffrement du flag transforme ensuite son contenu : il faut retrouver la recette et ses entrées. Un ZIP et un coffre-fort ne posent pas la même question. »", "details": "Les fichiers sont récupérés à partir de blocs XZ, dans un système de fichiers décrit comme SquashFS. flag.enc contient 35 octets. Les six octets affichés sont les six premiers du fichier fourni. XZ et ZIP sont des formats différents ; l’analogie concerne seulement la compression.", "qa": "L’absence de BA26 prouve-t-elle le chiffrement ? Non. C’est l’analyse ultérieure des fichiers et de ctf_unlock qui établit les deux couches.", "sources": "TAPO · POWERPOINT SLIDES 7–10 · FLAG.ENC · SOLVE.PY", "gap": "Les recherches initiales sont rapportées par le support. Aucun terminal simulé n’est présenté comme une capture réelle.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Tapo — la zone oubliée", "time": "45–60 secondes", "say": "« Le tournant, c’est une zone que la première extraction avait manquée. Imaginez un livre sans couverture : impossible de lire son titre, mais la table des matières et les pages existent toujours. Ici, les métadonnées indiquent encore où retrouver les fichiers. On peut donc les récupérer directement. Le livre était mal étiqueté, pas vide. »", "details": "Le script utilise une base à 0x1c0000, décompresse deux blocs de métadonnées XZ aux offsets 0x3a8236 et 0x3a887c, puis une table de fragments à 0x3aa18a. La fonction fragment_file lit les informations d’inode et de fragment pour extraire les données. Précision de la version (2), slide 14 : read_bytes lit le dump ; xz décompresse les blocs ; les tables décrivent les fichiers et la position de leurs données. fragment_file repère le bloc, le décompresse si nécessaire, puis découpe les octets du fichier. Les positions sont déjà connues et codées dans le script : il est spécifique à ce dump, sans découverte automatique. unlock contient le programme extrait, encrypted contient le message chiffré. Le PPT rapporte un superbloc SquashFS non reconnaissable.", "qa": "L’en-tête a-t-il été saboté volontairement ? Le support ne le démontre pas. On peut seulement dire qu’il n’était pas reconnaissable et que des métadonnées restaient exploitables.", "sources": "TAPO · POWERPOINT SLIDES 9–10 · SOLVE.PY", "gap": "L’analogie du livre est pédagogique. Les offsets sont lisibles dans le script, mais l’extraction n’a pas été relancée.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Tapo — les ingrédients", "time": "45–60 secondes", "say": "« On trouve le message chiffré, un petit programme nommé ctf_unlock, et le script de démarrage qui dit comment les relier. Ce dernier utilise l’identifiant de la caméra. Autrement dit, la caméra a fermé le coffre, mais elle a laissé la recette d’ouverture dans le même carton. Il reste à comprendre cette recette. »", "details": "Le fichier ctf_unlock fourni est un exécutable ELF 32 bits MIPS, statique et stripped. Le PPT indique que le script de démarrage lit devId, le transmet au programme avec flag.enc et écrit le résultat dans /tmp/flag.txt. solve.py récupère devId dans le dump via une expression régulière.", "qa": "L’identifiant est-il une clé secrète inaccessible ? Dans ce challenge, il est récupérable dans le dump. Cette observation ne démontre pas une vulnérabilité générale de tous les produits Tapo.", "sources": "TAPO · POWERPOINT SLIDES 11–12 · CTF_UNLOCK · FLAG.ENC · SOLVE.PY", "gap": "Le script de démarrage et le désassemblage sont décrits dans le PowerPoint ; ils ne sont pas fournis séparément. Le binaire n’a pas été exécuté.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Tapo — le masque", "time": "45–60 secondes", "say": "« Le programme fabrique une suite de nombres à partir de l’identifiant, d’un petit texte fixe et d’un compteur. Cette suite sert de masque. Le chiffrement utilise une opération appelée XOR : avec le même masque, on peut retrouver le message d’origine. L’agent a donc traduit la recette en Python. Pas de boule de cristal : les ingrédients étaient déjà dans le fichier. »", "details": "Recette lisible dans solve.py : SHA256(devId_ASCII || C500-CTF-v1 || LE32(compteur)), compteur à partir de zéro. Chaque empreinte donne 32 octets ; deux empreintes couvrent les 35 octets chiffrés. Le XOR est appliqué octet par octet. Le devId est utilisé tel quel en ASCII, sans conversion hexadécimale. Précisions de la version (2), slide 15 : re.search récupère la valeur du champ devId ; struct.pack encode le compteur sur quatre octets little-endian ; digest produit 32 octets par empreinte ; join assemble les blocs. Le calcul du nombre de blocs arrondit vers le haut : 35 octets nécessitent les compteurs 0 et 1. zip associe les octets chiffrés au flux et s’arrête au plus court : seuls 35 octets servent. Le symbole ^ réalise XOR, bytes reconstitue le résultat et decode le transforme en texte. Le test assert vérifie le format BA26, pas l’acceptation par la plateforme, confirmée séparément par l’utilisateur.", "qa": "A-t-on cassé SHA-256 ? Non. La fonction est utilisée dans le sens normal pour reconstruire un flux dont les entrées sont connues. Le script extrait ctf_unlock mais ne l’exécute pas.", "sources": "TAPO · SOLVE.PY · POWERPOINT SLIDE 13", "gap": "La recette est vérifiée par lecture du script. Aucun déchiffrement ni extraction n’a été relancé pour ces slides.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Tapo — le XOR, sans magie", "time": "45–60 secondes", "say": "« Voici une opération qui tient sur quatre bits. Si les deux bits sont identiques, XOR donne zéro ; sinon, il donne un. Qui trouve le résultat de la colonne de gauche ? Laisser quelques secondes. Un, un, zéro, zéro. Maintenant, reprenons ce résultat avec le même masque : on retrouve le message de départ. C’est exactement le principe utilisé pour enlever le masque du fichier chiffré. »", "details": "L’identité est (message XOR masque) XOR masque = message. Le script l’applique aux octets : chaque octet contient huit bits. Le masque réel vient des deux empreintes SHA-256 de la slide précédente.", "qa": "Est-ce un chiffrement faible par nature ? XOR est une opération ; la confidentialité dépend notamment du secret et de l’usage du masque. Ici, ses ingrédients sont récupérables.", "sources": "TAPO · POWERPOINT SLIDES 14–15 · OPÉRATION ^ DANS SOLVE.PY", "gap": "Mini-exemple inventé, explicitement distinct des octets réels. L’animation attend l’orateur avant de révéler la réponse.", "cues": ["Expliquer la règle et faire calculer le public.", "→ Révéler 1100.", "→ Réappliquer le même masque : 1010.", "→ Relier le calcul au déchiffrement du fichier."]}, {"title": "Tapo — comprendre le script", "time": "45–60 secondes", "say": "« La première ligne assemble l’identifiant, l’étiquette fixe et le compteur. La deuxième calcule un bloc du masque. Deux blocs suffisent ici. La troisième associe chaque octet du message chiffré à celui du masque, puis fait le XOR. Ce code reprend la logique du programme MIPS ; il n’exécute pas ce programme sur notre ordinateur. »", "details": "Les trois expressions sont issues du solve.py fourni, avec les arguments de sha256 abrégés par une ellipse. struct.pack encode un entier non signé sur quatre octets little-endian. digest renvoie 32 octets. Le nombre de blocs est (len(encrypted)+31)//32. zip s’arrête après les 35 octets chiffrés. En amont, fragment_file extrait ctf_unlock et flag.enc à partir des tables décompressées ; re.search retrouve devId. Les offsets sont fixes : ce solveur est spécifique au dump. Le test assert contrôle le format BA26{…}, pas une validation serveur.", "qa": "Pourquoi le programme est-il extrait s’il n’est pas lancé ? Il documente la recette. Le solveur reproduit ensuite cette logique en Python.", "sources": "TAPO · SOLVE.PY · POWERPOINT SLIDES 17–18", "gap": "Lecture statique du script fourni. Aucun déchiffrement, téléchargement ni exécution du binaire effectué pour cette présentation.", "cues": ["Relier key à devId et expliquer le compteur.", "→ SHA-256 fabrique le masque.", "→ XOR retrouve les octets du texte.", "→ Distinguer recette, résultat conservé et soumission."]}, {"title": "Tapo — le résultat", "time": "45–60 secondes", "say": "« Le fichier flag.txt fourni contient ce texte, exactement identique à celui du PowerPoint. On dispose donc du résultat et d’un script qui décrit une procédure pour le retrouver depuis le dump. La soumission a été confirmée par la plateforme : le challenge est validé. La caméra avait gardé son secret et son mode d’emploi au même endroit. »", "details": "Les fichiers reçus sont Resolution_CTF_Tapo.pptx, solve.py, ctf_unlock, flag.enc et flag.txt. flag.enc et flag.txt font chacun 35 octets. Le flag lu correspond au support. Le script vérifie la forme BA26{…}, mais cette vérification n’est pas une validation serveur.", "qa": "Avons-nous reproduit le solve ici ? Non : les fichiers ont été lus, et le script inspecté. Le dump n’a pas été fourni dans cette demande, et aucune exécution n’a été réalisée. La reproduction annoncée est celle du PowerPoint source.", "sources": "TAPO · FLAG.TXT FOURNI · SOUMISSION CONFIRMÉE PAR L’UTILISATEUR", "gap": "La concordance entre flag.txt et le PowerPoint est vérifiée. L’utilisateur a confirmé la soumission à la plateforme après la réception du PowerPoint ; cette confirmation remplace le statut provisoire du support. La provenance de la résolution et son auteur ne sont pas précisés ; aucune attribution à un agent n’est inventée.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}, {"title": "Conclusion", "time": "30 secondes", "say": "« Les attaques sont différentes, mais on peut les raconter avec les mêmes questions. Quel était le verrou ? Quelle hypothèse était fragile ? Et quelle preuve nous permet de dire que cela a fonctionné ? C’est ce passage du résultat au raisonnement qui nous permet de nous approprier le travail des agents. »", "details": "Les schémas de cette présentation simplifient les mécanismes. Les notes rattachent chaque affirmation aux journaux et aux artefacts disponibles. Les captures annotées produites après l’événement sont identifiées comme telles.", "qa": "Les chapitres peuvent être présentés séparément. Pour un créneau court, commencer par les embeddings, id_please et wrong_path. Les mécanismes les plus spécialisés restent détaillés dans leurs notes.", "sources": "JOURNAUX ET ARTEFACTS CONSERVÉS · PRÉSENTATION DOCUMENTAIRE", "gap": "Schémas pédagogiques fondés sur les fichiers. Les animations ne représentent pas les temps réels du solve.", "cues": ["Présenter le défi.", "→ Faire apparaître l’idée suivante.", "→ Conclure avec la preuve ou la leçon."]}];
window.EXTRA_EVIDENCE={"embeddings": {"title": "Le texte retrouvé dans les vecteurs", "image": "assets/embeddings.png", "caption": "lost_in_embedding/claude/out-01.txt et capture claude-03-flag-hires.annotated.png. Rendu haute résolution ajouté après l’événement à partir de la sortie conservée. Distances après correction : 0,000 à 0,004 ; cosinus : 1,000."}, "vm": {"title": "Une seule interprétation satisfait les exemples", "image": "assets/vm.png", "caption": "universal_translator/codex/solver-output.txt. Résultat conservé du solve par Codex ; annotation ajoutée après l’événement."}, "beacon": {"title": "Le vrai enregistrement décodé", "image": "assets/beacon.png", "caption": "silent_beacon : capture du solveur codex/solve.py, réalisée lors du backfill à partir du dump local. Le résultat concorde avec le journal de Codex à 18:49."}, "decoy": {"title": "Le faux flag et les données utiles", "image": "assets/decoy.png", "caption": "silent_beacon : rodata conservée. Le faux flag est présent en clair ; le chemin de déverrouillage décode une autre zone. Aucun élément conservé ne dit si le leurre a été soumis."}, "badge": {"title": "Le badge gagnant", "image": "assets/badge.png", "caption": "peak_privilege/screenshots/claude-01-admin-badge.annotated.png. Le journal rapporte ADMIN = 0,996 et l’accès accordé. Les réponses HTTP et leur ordre exact ne sont pas conservés."}, "maze": {"title": "Le chemin dans le labyrinthe", "image": "assets/maze.annotated.png", "caption": "wrong_path : rendu local du labyrinthe 201 × 201 et du chemin BFS conservé, annoté après l’événement. Ce n’est pas une capture de l’application web ; aucune n’a été gardée."}, "mazeout": {"title": "Le résultat du parcours", "image": "assets/maze-output.png", "caption": "wrong_path/claude/out-01.txt : deux entrées, 2 783 positions sur le chemin et le texte du flag. Capture ajoutée lors de la reconstruction."}, "rucher": {"title": "Du réseau Zigbee au flag", "image": "assets/rucher.png", "caption": "rucher/claude/out-01-solve.txt : clé réseau, identité de l’appareil, six fragments et flag. Sortie conservée d’une reproduction hors ligne lors du backfill."}, "driver-nonce": {"title": "Le nombre temporaire est limité à 255 valeurs", "image": "assets/nonce.annotated.png", "caption": "driver_radio : capture annotée de ecdsa_sign. Le journal de 20:05 documente aussi cette limite. Le désassemblage complet n’a pas été conservé."}, "driver-recovery": {"title": "Le solveur vérifie la clé candidate", "image": "assets/recovery.annotated.png", "caption": "driver_radio : capture de claude/recover.py, rendue et annotée après l’événement. Le calcul est suivi d’une comparaison avec la clé publique du pilote."}, "driver-result": {"title": "Les 22 commandes sont acceptées", "image": "assets/flag.annotated.png", "caption": "driver_radio : capture annotée du résultat, corroborée par claude/final_resp.txt et le journal de 20:19. Aucun exploit n’a été relancé pour la présentation."}, "tapo-photo-1": {"title": "La caméra ouverte", "image": "assets/tapo-image1.jpg", "caption": "Photographie fournie par l’utilisateur dans Resolution_CTF_Tapo.pptx, slides 4–5. Elle montre le matériel, sans établir à elle seule le brochage ou la chronologie du montage."}, "tapo-photo-2": {"title": "La carte et ses connexions", "image": "assets/tapo-image2.jpg", "caption": "Photographie fournie par l’utilisateur dans Resolution_CTF_Tapo.pptx, slides 4–5. Elle montre le matériel, sans établir à elle seule le brochage ou la chronologie du montage."}, "tapo-photo-3": {"title": "L’adaptateur Waveshare", "image": "assets/tapo-image3.jpg", "caption": "Photographie fournie par l’utilisateur dans Resolution_CTF_Tapo.pptx, slides 4–5. Elle montre le matériel, sans établir à elle seule le brochage ou la chronologie du montage."}, "tapo-photo-4": {"title": "Le montage de lecture", "image": "assets/tapo-image4.jpg", "caption": "Photographie fournie par l’utilisateur dans Resolution_CTF_Tapo.pptx, slides 4–5. Elle montre le matériel, sans établir à elle seule le brochage ou la chronologie du montage."}};